        if tgt_i == -1:
            m[row, index[(-1, 1, 1)]] = 1.0
            continue
        if tgt_i == last:
            m[row, index[(last, 0, 0)]] = 1.0
            continue
        if tgt_i == 0:
            up = escape if arr == -1 else 0.0
        else:
            up = up_below if arr == -1 else up_above
        for onward, w in ((-1, 1.0 - up), (1, up)):
            tgt = index.get((tgt_i, arr, onward))
            if tgt is not None:
                m[row, tgt] += w
    return states, m, times
